	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		CompensationPackage
	 */
		public CompensationPackage createCompensationPackage( CreateCompensationPackageCommand command ) {

		CompensationPackage entity = new CompensationPackage();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCompensationPackageId( command.getCompensationPackageId() );
            entity.setEffectiveFrom( command.getEffectiveFrom() );
            entity.setEffectiveTo( command.getEffectiveTo() );
            entity.setCurrency( command.getCurrency() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of CompensationPackage {0} ", entity.toString() );

		return entity;
	}

